-- ---- 2. the transform target 98233 "Head Explode" morphs into --------------
-- The aura is TRANSFORM (56) and its EffectMiscValue names creature 53113,
-- which exists on neither side raw or offset -- so without this the worm
-- morphs into nothing, exactly the trap 145_ hit with 97678. r26 remaps the
-- spell to 3653113 and this creates it.
--
-- Two deliberate departures from a verbatim clone:
--   * AIName is forced to '' -- nelt gives 53113 AIName='SmartAI' but has ZERO
--     smart_scripts rows for it, so copying it verbatim would manufacture a
--     fresh "has SmartAI enabled but no SmartAI entries" line.
--   * Display 38153 is substituted with 38152. 38153 is absent from the
--     deployed CreatureDisplayInfo.dbc (28,592 records); 38152 is present and
--     is the same worm, already in use by the caster 3653112.
SET @OFF := 3600000;

DELETE FROM acore_world.`creature_template` WHERE `entry` = 3653113;

INSERT INTO acore_world.`creature_template`
(`entry`,`KillCredit1`,`KillCredit2`,`name`,`subname`,`IconName`,`gossip_menu_id`,`minlevel`,`maxlevel`,`exp`,`faction`,`npcflag`,`speed_walk`,`speed_run`,`speed_swim`,`speed_flight`,`rank`,`dmgschool`,`DamageModifier`,`BaseAttackTime`,`RangeAttackTime`,`BaseVariance`,`RangeVariance`,`unit_class`,`unit_flags`,`unit_flags2`,`dynamicflags`,`family`,`type`,`type_flags`,`lootid`,`pickpocketloot`,`skinloot`,`PetSpellDataId`,`VehicleId`,`mingold`,`maxgold`,`AIName`,`MovementType`,`HoverHeight`,`HealthModifier`,`ManaModifier`,`ArmorModifier`,`RacialLeader`,`movementId`,`RegenHealth`,`flags_extra`,`ScriptName`,`VerifiedBuild`)
SELECT entry+@OFF, IF(KillCredit1>0,KillCredit1+@OFF,0), IF(KillCredit2>0,KillCredit2+@OFF,0), name, subname, IconName, gossip_menu_id, minlevel, maxlevel, LEAST(exp,2), faction_A, npcflag, speed_walk, speed_run, speed_swim, speed_fly, `rank`, dmgschool, dmg_multiplier, baseattacktime, rangeattacktime, 1, 1, unit_class, unit_flags, unit_flags2, dynamicflags, family, type, type_flags, 0, 0, 0, PetSpellDataId, VehicleId, mingold, maxgold,
       '',
       MovementType, HoverHeight, Health_mod, Mana_mod, Armor_mod, RacialLeader, movementId, RegenHealth, flags_extra, '', 0
FROM nelt_world.creature_template
WHERE entry = 53113;

DELETE FROM acore_world.`creature_template_model` WHERE `CreatureID` = 3653113;

INSERT INTO acore_world.`creature_template_model` (`CreatureID`,`Idx`,`CreatureDisplayID`,`DisplayScale`,`Probability`,`VerifiedBuild`)
VALUES (3653113,0,38152,1,1,0);

-- ---- 3. the 15 action lists (77 rows) --------------------------------------
-- source_type 9. Every row in this set carries event_type 0, so the fork's
-- event_param5/6 divergence from upstream (distance lives in 5/6 here, not 1/2)
-- cannot bite -- but that is why the column list is written out rather than
-- SELECT *: nelt_world.smart_scripts has no event_param5/6 at all.
DELETE FROM acore_world.`smart_scripts` WHERE `source_type` = 9 AND `entryorguid` IN (4941300,5270500,5299000,5310700,5310701,5311200,5316300,5323400,5323401,5323402,5323403,5323404,5335400,5402500,5407000);

INSERT INTO acore_world.`smart_scripts`
(`entryorguid`,`source_type`,`id`,`link`,`event_type`,`event_phase_mask`,`event_chance`,`event_flags`,`event_param1`,`event_param2`,`event_param3`,`event_param4`,`event_param5`,`event_param6`,`action_type`,`action_param1`,`action_param2`,`action_param3`,`action_param4`,`action_param5`,`action_param6`,`target_type`,`target_param1`,`target_param2`,`target_param3`,`target_param4`,`target_x`,`target_y`,`target_z`,`target_o`,`comment`)
SELECT entryorguid, source_type, id, link, event_type, event_phase_mask, event_chance, event_flags,
       event_param1, event_param2, event_param3, event_param4, 0, 0,
       action_type,
       CASE WHEN action_type = 33 AND action_param1 = 53234 THEN 3653234 ELSE action_param1 END,
       action_param2, action_param3, action_param4, action_param5, action_param6,
       target_type,
       CASE WHEN target_type = 19 AND target_param1 = 53366 THEN 3653366
            WHEN target_type = 19 AND target_param1 = 52669 THEN 3652669
            ELSE target_param1 END,
       target_param2, target_param3, target_param4, target_x, target_y, target_z, target_o,
       CONCAT('MF action list restore - src ', entryorguid, '.', id)
FROM nelt_world.smart_scripts
WHERE source_type = 9 AND entryorguid IN (4941300,5270500,5299000,5310700,5310701,5311200,5316300,5323400,5323401,5323402,5323403,5323404,5335400,5402500,5407000);

-- ---- 4. the four waypoint paths those lists start --------------------------
-- 20 points. Ids stay RAW, matching 16_'s already-live path 53912. nelt's
-- waypoints table has no orientation/delay columns, so both default to 0 --
-- which is what every other path in this downport carries.
DELETE FROM acore_world.`waypoints` WHERE `entry` IN (52990,53234,54025,5323400);

INSERT INTO acore_world.`waypoints` (`entry`,`pointid`,`position_x`,`position_y`,`position_z`,`orientation`,`delay`,`point_comment`)
SELECT entry, pointid, position_x, position_y, position_z, 0, 0, point_comment
FROM nelt_world.waypoints WHERE entry IN (52990,53234,54025,5323400);

