--       AND NOT EXISTS (SELECT 1 FROM smart_scripts a
--         WHERE a.entryorguid=s.action_param1 AND a.source_type=9)  -> 0
--   * Errors.log keeps exactly ONE waypoint line for this area -- the
--     5391201 / 5391200 upstream gap described in the header.
